{
  "accounts": {
    "notes": "Account identity and billing configuration.",
    "writable": false,
    "selectors": [
      "account_id",
      "org"
    ],
    "fields": {
      "account_id": {
        "type": "string",
        "required": true
      },
      "org": {
        "type": "string",
        "required": true
      },
      "plan": {
        "type": "string",
        "enum": [
          "free",
          "self_serve",
          "enterprise"
        ],
        "required": true
      },
      "plan_name": {
        "type": "string",
        "required": true
      },
      "billing_channel": {
        "type": "string",
        "enum": [
          "direct",
          "aws_marketplace",
          "gcp_marketplace"
        ],
        "required": true
      },
      "status": {
        "type": "string",
        "enum": [
          "active",
          "suspended"
        ],
        "required": true
      },
      "payment_method": {
        "type": "string",
        "enum": [
          "card",
          "invoice",
          "marketplace",
          "none"
        ],
        "required": true
      },
      "created_on": {
        "type": "date",
        "required": true
      }
    }
  },
  "contacts": {
    "notes": "Account contact records.",
    "writable": false,
    "selectors": [
      "contact_id",
      "account_id",
      "email"
    ],
    "fields": {
      "contact_id": {
        "type": "string",
        "required": true
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "name": {
        "type": "string",
        "required": true
      },
      "email": {
        "type": "string",
        "required": true
      },
      "role": {
        "type": "string",
        "enum": [
          "owner",
          "billing_admin",
          "developer"
        ],
        "required": true
      }
    }
  },
  "contracts": {
    "notes": "Signed account terms and service dates.",
    "writable": false,
    "selectors": [
      "contract_id",
      "account_id"
    ],
    "fields": {
      "contract_id": {
        "type": "string",
        "required": true
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "sla": {
        "type": "boolean",
        "required": true
      },
      "signed_terms": {
        "type": "string",
        "list": true,
        "required": true
      },
      "start_on": {
        "type": "date",
        "required": true
      },
      "end_on": {
        "type": "date",
        "nullable": true,
        "required": true
      }
    }
  },
  "invoices": {
    "notes": "Invoice header records.",
    "writable": false,
    "selectors": [
      "invoice_id",
      "account_id"
    ],
    "fields": {
      "invoice_id": {
        "type": "string",
        "required": true
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "period_start": {
        "type": "date",
        "required": true
      },
      "period_end": {
        "type": "date",
        "required": true
      },
      "issued_on": {
        "type": "date",
        "required": true
      },
      "status": {
        "type": "string",
        "enum": [
          "open",
          "paid"
        ],
        "required": true
      },
      "total_cents": {
        "type": "integer",
        "required": true
      }
    }
  },
  "invoice_lines": {
    "notes": "Invoice line details and linked requests.",
    "writable": false,
    "selectors": [
      "line_id",
      "invoice_id"
    ],
    "fields": {
      "line_id": {
        "type": "string",
        "required": true
      },
      "invoice_id": {
        "type": "string",
        "ref": "invoices",
        "required": true
      },
      "description": {
        "type": "string",
        "required": true
      },
      "product": {
        "type": "string",
        "enum": [
          "hosted_api",
          "embeddings",
          "batch",
          "dedicated",
          "plan_fee",
          "tax"
        ],
        "required": true
      },
      "period_start": {
        "type": "date",
        "required": true
      },
      "period_end": {
        "type": "date",
        "required": true
      },
      "amount_cents": {
        "type": "integer",
        "required": true
      },
      "request_ids": {
        "type": "string",
        "list": true,
        "ref": "usage",
        "required": true
      }
    }
  },
  "usage": {
    "notes": "Usage request records.",
    "writable": false,
    "selectors": [
      "request_id",
      "account_id",
      "line_id"
    ],
    "fields": {
      "request_id": {
        "type": "string",
        "required": true
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "at": {
        "type": "utc",
        "required": true
      },
      "http_status": {
        "type": "integer",
        "required": true
      },
      "billed_tokens": {
        "type": "integer",
        "required": true
      },
      "cached_tokens": {
        "type": "integer",
        "required": true
      },
      "line_id": {
        "type": "string",
        "ref": "invoice_lines",
        "nullable": true,
        "required": true
      }
    }
  },
  "credit_grants": {
    "notes": "Granted account credits.",
    "writable": false,
    "selectors": [
      "grant_id",
      "account_id"
    ],
    "fields": {
      "grant_id": {
        "type": "string",
        "required": true
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "kind": {
        "type": "string",
        "enum": [
          "promotional",
          "service",
          "prepaid"
        ],
        "required": true
      },
      "amount_cents": {
        "type": "integer",
        "required": true
      },
      "remaining_cents": {
        "type": "integer",
        "required": true
      },
      "granted_on": {
        "type": "date",
        "required": true
      },
      "expires_on": {
        "type": "date",
        "nullable": true,
        "required": true
      }
    }
  },
  "credit_notes": {
    "notes": "Issued credit note records.",
    "writable": true,
    "selectors": [
      "credit_note_id",
      "account_id",
      "invoice_id"
    ],
    "fields": {
      "credit_note_id": {
        "type": "string",
        "required": false
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "invoice_id": {
        "type": "string",
        "ref": "invoices",
        "required": true
      },
      "line_ids": {
        "type": "string",
        "list": true,
        "ref": "invoice_lines",
        "required": true
      },
      "amount_cents": {
        "type": "integer",
        "required": true
      },
      "reason": {
        "type": "string",
        "enum": [
          "duplicate",
          "service_credit",
          "goodwill"
        ],
        "required": true
      },
      "memo": {
        "type": "string",
        "default": "",
        "required": false
      },
      "status": {
        "type": "string",
        "enum": [
          "issued"
        ],
        "default": "issued",
        "required": false
      },
      "at": {
        "type": "integer",
        "required": false
      }
    }
  },
  "disputes": {
    "notes": "Billing dispute records.",
    "writable": true,
    "selectors": [
      "dispute_id",
      "account_id"
    ],
    "fields": {
      "dispute_id": {
        "type": "string",
        "required": false
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "invoice_id": {
        "type": "string",
        "ref": "invoices",
        "nullable": true,
        "default": null,
        "required": false
      },
      "line_ids": {
        "type": "string",
        "list": true,
        "ref": "invoice_lines",
        "default": [],
        "required": false
      },
      "reason": {
        "type": "string",
        "enum": [
          "duplicate_charge",
          "incorrect_amount",
          "unrecognized_usage"
        ],
        "nullable": true,
        "default": null,
        "required": false
      },
      "request_ids": {
        "type": "string",
        "list": true,
        "ref": "usage",
        "default": [],
        "required": false
      },
      "window": {
        "type": "string",
        "default": "",
        "required": false
      },
      "status": {
        "type": "string",
        "enum": [
          "draft",
          "submitted"
        ],
        "required": true
      },
      "at": {
        "type": "integer",
        "required": false
      }
    }
  },
  "cases": {
    "notes": "Support case records.",
    "writable": true,
    "selectors": [
      "case_id",
      "account_id"
    ],
    "fields": {
      "case_id": {
        "type": "string",
        "required": false
      },
      "account_id": {
        "type": "string",
        "ref": "accounts",
        "required": true
      },
      "team": {
        "type": "string",
        "enum": [
          "billing_ops",
          "billing_engineering",
          "finance",
          "legal",
          "account_team",
          "partnerships",
          "telemetry",
          "sre",
          "platform"
        ],
        "nullable": true,
        "default": null,
        "required": false
