"""Tool declarations connect workspace methods to the runtime's JSON tool interface."""
from __future__ import annotations

import inspect
import re
from collections.abc import Callable
from dataclasses import dataclass
from enum import StrEnum
from typing import TYPE_CHECKING, get_type_hints

from pydantic import create_model

from .jsontypes import Json, JsonObject, is_json_object

if TYPE_CHECKING:
    from .agent_context import ModelGateway
    from .billing import Billing
    from .developer import Developer
    from .hooks import ToolRunner


class ToolType(StrEnum):
    READ = "read"
    WRITE = "write"
    THINK = "think"
    GENERIC = "generic"


_TOOL_TYPES: dict[object, ToolType] = {}


def is_tool[**P](tool_type: ToolType = ToolType.READ) -> Callable[[Callable[P, object]], Callable[P, object]]:
    def decorate(function: Callable[P, object]) -> Callable[P, object]:
        _TOOL_TYPES[function] = tool_type
        return function

    return decorate


@dataclass(frozen=True)
class Tool:
    name: str
    description: str
    parameters: JsonObject

    @property
    def openai_schema(self) -> JsonObject:
        return {"type": "function", "name": self.name, "description": self.description, "parameters": self.parameters}


def _docstring_parts(doc: str | None) -> tuple[str, dict[str, str]]:
    """Split a Google-style docstring into (description, {arg: description})."""
    head, _, tail = inspect.cleandoc(doc or "").partition("Args:")
    tail = re.split(r"\n\s*(?:Returns|Raises|Examples?):", tail)[0]
    args: dict[str, str] = {}
    current: str | None = None
    for line in tail.splitlines():
        match = re.match(r"\s*(\w+)(?:\s*\([^)]*\))?:\s*(.*)", line)
        if match:
            current = match.group(1)
            args[current] = match.group(2).strip()
        elif current is not None and line.strip():
            args[current] += " " + line.strip()
    return " ".join(head.split()), args


def tool_from_method[**P](method: Callable[P, object]) -> Tool:
    description, arg_docs = _docstring_parts(method.__doc__)
    hints: dict[str, object] = get_type_hints(method)
    fields: dict[str, tuple[object, object]] = {}
    for name, parameter in inspect.signature(method).parameters.items():
        if name == "self":
            continue
        annotation = hints.get(name, object)
        default: object = ...
        if parameter.default is not inspect.Parameter.empty:
            default = parameter.default
        fields[name] = (annotation, default)
    schema_value: object = create_model(
        method.__name__,
        __config__=None,
        __doc__=None,
        __base__=None,
        __module__=__name__,
        __validators__=None,
        __cls_kwargs__=None,
        __qualname__=None,
        **fields,
    ).model_json_schema()
    if not is_json_object(schema_value):
        raise TypeError(f"tool schema for {method.__name__} must be a JSON object")
    schema = schema_value
    for name, text in arg_docs.items():
        properties = schema.get("properties")
        if not is_json_object(properties):
            continue
        parameter_schema = properties.get(name)
        if is_json_object(parameter_schema):
            parameter_schema["description"] = text
    schema.pop("title", None)
    return Tool(method.__name__, description, schema)


class ToolKitBase:
    """Anything with `@is_tool` methods; `get_tools()` lists them, `call()` runs one.

    The runtime sets `gateway` (ModelGateway), `runner`, `billing`, and `developer` before any tool runs.
    """

    gateway: ModelGateway
    runner: ToolRunner
    billing: Billing | None = None
    developer: Developer | None = None

    def get_tools(self) -> list[Tool]:
        tools = []
        for _, member in inspect.getmembers(self, inspect.ismethod):
            if member.__func__ in _TOOL_TYPES:
                tools.append(tool_from_method(member))
        return tools

    def call(self, name: str, /, **arguments: Json) -> object:
        for _, method in inspect.getmembers(self, inspect.ismethod):
            if method.__name__ == name and method.__func__ in _TOOL_TYPES:
                return method(**arguments)
        raise ValueError(f"Tool {name} not found")
"""Run workspace agents in a sandbox and exchange JSON messages with the host."""
from __future__ import annotations

import importlib
import json
import os
import sys
import traceback
from enum import StrEnum
from pathlib import Path
from types import ModuleType
from typing import Protocol, TextIO, TypeGuard, runtime_checkable

from .agent_context import (
    ActionInterface,
    AgentBuildContext,
    KitResources,
    ModelConfig,
    ModelGateway,
    activate_agent_context,
)
from .billing import Billing
from .developer import Developer
from .hooks import HookKitBase, ToolRunner
from .jsontypes import Json, JsonObject, is_json_object
from .messages import Message, ToolCall, UserMessage, from_dict, to_dict
from .toolkit import ToolKitBase

RUNTIME_CONFIG = {"company": "Redwood Inference", "role": "billing_support"}
_protocol_out = sys.stdout
_protocol_in = sys.stdin


class HostOp(StrEnum):
    INIT = "init"
    TURN = "turn"
    TOOLS = "tools"


class HostCall(StrEnum):
    MODEL = "model"
    EMBED = "embed"
    BILLING = "billing"
    DEVELOPER = "developer"


@runtime_checkable
class SupportAgent(Protocol):
    def get_init_state(self, *, message_history: list[Message]) -> object: ...

    def generate_next_message(self, message: Message, state: object) -> tuple[Message, object]: ...


@runtime_checkable
class StopsConversation(Protocol):
    def is_stop(self, message: Message) -> bool: ...


class WorkspaceFactory(Protocol):
    def __call__(self) -> object: ...


def _is_factory(value: object) -> TypeGuard[WorkspaceFactory]:
    return callable(value)


def _write(payload: JsonObject) -> None:
    _protocol_out.write(json.dumps(payload) + "\n")
    _protocol_out.flush()


def _read() -> JsonObject:
    line = _protocol_in.readline()
    if not line:
        raise SystemExit(0)
    value = json.loads(line)
    if not is_json_object(value):
        raise TypeError("wire message must be an object")
    return value


def _ask(payload: JsonObject) -> JsonObject:
    _write(payload)
    reply = _read()
    if not reply.get("ok"):
        error = reply.get("error", "host rejected the request")
        raise RuntimeError(str(error))
    return reply


def _factory(module: ModuleType, name: str) -> WorkspaceFactory:
    candidate = module.__dict__.get(name)
    if not _is_factory(candidate):
        raise TypeError(f"workspace module has no callable {name}")
    return candidate


def _load_toolkit() -> ToolKitBase:
    instance = _factory(importlib.import_module("tools"), "Tools")()
    if not isinstance(instance, ToolKitBase):
        raise TypeError("workspace Tools must inherit ToolKitBase")
    return instance


def _load_hooks(root: Path) -> HookKitBase | None:
    if not (root / "hooks.py").is_file():
        return None
    instance = _factory(importlib.import_module("hooks"), "Hooks")()
    if not isinstance(instance, HookKitBase):
        raise TypeError("workspace Hooks must inherit HookKitBase")
    return instance


def _object(value: Json, name: str) -> JsonObject:
    if not is_json_object(value):
        raise TypeError(f"{name} must be an object")
    return value


def _model_config(value: Json) -> ModelConfig:
    data = _object(value, "model configuration")
    model = data.get("model")
    constraints = data.get("constraints", {})
    if not isinstance(model, str) or not is_json_object(constraints):
        raise TypeError("model configuration is invalid")
    return ModelConfig(model, constraints)


def _model_configs(value: Json) -> tuple[ModelConfig, ...]:
    if not isinstance(value, list):
        raise TypeError("model configurations must be a list")
    return tuple(_model_config(item) for item in value)


def _init_gateway(init: JsonObject) -> ModelGateway:
    models = _model_configs(init["models"])
    embeddings = _model_configs(init.get("embedding_models", []))
    return ModelGateway(models, _ask, embeddings)


def _build_agent(root: Path, toolkit: ToolKitBase, gateway: ModelGateway, runner: ToolRunner) -> SupportAgent:
    billing = Billing(_ask)
    toolkit.gateway = gateway
    toolkit.runner = runner
    toolkit.billing = billing
    toolkit.developer = Developer(_ask)
    context = AgentBuildContext(
        action_interface=ActionInterface(tuple(toolkit.get_tools())),
        resources=KitResources.from_root(root),
        model_gateway=gateway,
        runtime_config=RUNTIME_CONFIG,
        billing=billing,
    )
    with activate_agent_context(context):
        agent = _factory(importlib.import_module("agent"), "create_agent")()
    if not isinstance(agent, SupportAgent):
        raise TypeError("workspace agent does not implement the support-agent protocol")
    return agent


def _initial_state(agent: SupportAgent, init: JsonObject) -> object:
    message = from_dict(_object(init["first_message"], "first_message"))
    return agent.get_init_state(message_history=[message])


def _stop(agent: SupportAgent, message: Message) -> bool:
    if isinstance(agent, StopsConversation):
        return bool(agent.is_stop(message))
    return False


def _turn(request: JsonObject, agent: SupportAgent, runner: ToolRunner, state: object) -> tuple[JsonObject, object]:
    message = from_dict(_object(request["message"], "message"))
    if isinstance(message, UserMessage):
        message.content = runner.user_message(message.content or "")
    response, new_state = agent.generate_next_message(message, state)
    return {"ok": True, "message": to_dict(response), "stop": _stop(agent, response)}, new_state


def _tool_calls(value: Json) -> list[ToolCall]:
    if not isinstance(value, list):
        raise TypeError("tool_calls must be a list")
    calls: list[ToolCall] = []
    for item in value:
        data = _object(item, "tool call")
        call_id = data.get("id")
        name = data.get("name")
        arguments = data.get("arguments", {})
        if not isinstance(call_id, str) or not isinstance(name, str) or not is_json_object(arguments):
            raise TypeError("tool call is invalid")
        calls.append(ToolCall(call_id, name, arguments))
    return calls


def _tools(request: JsonObject, runner: ToolRunner) -> JsonObject:
    calls = _tool_calls(request["tool_calls"])
    return {"ok": True, "tool_messages": [to_dict(runner.run(call)) for call in calls]}


def _handle_request(
    request: JsonObject,
    agent: SupportAgent,
    runner: ToolRunner,
    state: object,
) -> tuple[JsonObject | None, object]:
    operation = request.get("op")
    if operation == HostOp.TURN:
        response, new_state = _turn(request, agent, runner, state)
        return response, new_state
    if operation == HostOp.TOOLS:
        return _tools(request, runner), state
    return None, state


def _serve(agent: SupportAgent, runner: ToolRunner, state: object) -> None:
    while True:
        request = _read()
        try:
            response, state = _handle_request(request, agent, runner, state)
            if response is None:
                return
            _write(response)
        except Exception:
            _write({"ok": False, "error": traceback.format_exc(limit=8)})


def _redirect_stdio(null_input: TextIO) -> None:
    global _protocol_out, _protocol_in
    _protocol_out, _protocol_in = sys.stdout, sys.stdin
    sys.stdout, sys.stdin = sys.stderr, null_input


def _run_candidate() -> None:
    init = _read()
    root = Path.cwd()
    sys.path.insert(0, str(root))
    toolkit = _load_toolkit()
    runner = ToolRunner(toolkit, _load_hooks(root))
    gateway = _init_gateway(init)
    agent = _build_agent(root, toolkit, gateway, runner)
    state = _initial_state(agent, init)
    _write({"ok": True})
    _serve(agent, runner, state)


def main() -> None:
    with open(os.devnull) as null_input:
        _redirect_stdio(null_input)
        _run_candidate()


if __name__ == "__main__":
    main()
"""Hook declarations connect workspace callbacks to message and tool execution.

The runtime, not the agent, fires them, so they hold for every tool call,
including those a subagent makes.
"""
from __future__ import annotations

import inspect
import json
from collections.abc import Callable
from dataclasses import dataclass
from enum import StrEnum
from fnmatch import fnmatch
from types import MethodType
from typing import TYPE_CHECKING, Protocol, runtime_checkable

from .jsontypes import JsonObject, is_json_object
from .messages import ToolCall, ToolMessage

if TYPE_CHECKING:
    from .toolkit import ToolKitBase


class HookEvent(StrEnum):
    USER_MESSAGE = "user_message"
    PRE_TOOL = "pre_tool"
    POST_TOOL = "post_tool"


EVENTS = tuple(event.value for event in HookEvent)


@dataclass(frozen=True)
class HookBinding:
    event: HookEvent
    match: str


_HOOKS: dict[object, HookBinding] = {}


@runtime_checkable
class _UserMessageHook(Protocol):
    def __call__(self, text: str) -> object: ...


@runtime_checkable
class _PreToolHook(Protocol):
    def __call__(self, tool: str, arguments: JsonObject) -> object: ...


@runtime_checkable
class _PostToolHook(Protocol):
    def __call__(self, tool: str, arguments: JsonObject, result: object) -> object: ...


class Blocked(Exception):
    """Raise from a pre_tool hook to refuse the call; the message goes back to the model."""


def hook[F](event: str, match: str = "*") -> Callable[[F], F]:
    """Run the method on `event`; tool events only for tool names matching the `match` glob.

    user_message(self, text) -> str | None   replacement text, or None to keep it
    pre_tool(self, tool, args) -> dict | None  replacement arguments; raise Blocked to refuse
    post_tool(self, tool, args, result) -> object | None  replacement result
    """
    if event not in EVENTS:
        raise ValueError(f"unknown hook event {event!r}; use one of {EVENTS}")

    def decorate(function: F) -> F:
        _HOOKS[function] = HookBinding(HookEvent(event), match)
        return function

    return decorate


class HookKitBase:
    """Anything with `@hook` methods. Hooks for one event run in method-name order."""

    def hooks(self, event: str, tool: str = "") -> list[MethodType]:
        handlers: list[MethodType] = []
        for _, member in inspect.getmembers(self, inspect.ismethod):
            binding = _HOOKS.get(member.__func__)
            if binding is not None and binding.event == event and fnmatch(tool, binding.match):
                handlers.append(member)
        return handlers


class ToolRunner:
    """Runs tool calls through pre_tool and post_tool hooks. Every tool call goes through here."""

    def __init__(self, toolkit: ToolKitBase, hooks: HookKitBase | None = None) -> None:
        self.toolkit = toolkit
        self._hooks = hooks or HookKitBase()

    def user_message(self, text: str) -> str:
        for handler in self._hooks.hooks(HookEvent.USER_MESSAGE):
            if not isinstance(handler, _UserMessageHook):
                raise TypeError(f"{handler.__name__} is not a user_message hook")
            if (replaced := handler(text)) is not None:
                if not isinstance(replaced, str):
                    raise TypeError(f"{handler.__name__} must return a string or None")
                text = replaced
        return text

    def run(self, call: ToolCall) -> ToolMessage:
        try:  # a failing tool or hook is data for the agent, not a crash
            args = dict(call.arguments)
